  for (const z of [z0 + .02, z1 - .02]) pos.push(a[0], z, -a[1], b[0], z, -b[1]);
  for (let i = 0; i <= n; i++) { const x = a[0] + (b[0] - a[0]) * i / n, y = a[1] + (b[1] - a[1]) * i / n; pos.push(x, z0, -y, x, z1, -y); }
